```javascript
// main.js
import * as AWS from 'aws-cdk/aws';

// Создание нового AWS Lambda функция
const lambdaFunction = new AWS.Lambda.Function(
  {
    name: 'my-function',
    code: AWS Lambda Function Template,
    // Опции запуска
